/**
 * The template library — the heart of FormMitra's template mode.
 *
 * These ten JSON files are imported statically, which means Vite bundles them
 * into the JavaScript build and the service worker caches them. That is what
 * makes explanations work with the phone in aeroplane mode.
 *
 * Nothing in here is generated by a model. Every explanation was written and
 * reviewed by the team, which is why template mode cannot hallucinate.
 */

import nspScholarship from './nsp-scholarship.json'
import pan93 from './pan-93.json'
import rationCard from './ration-card.json'
import pensionLifeCertificate from './pension-life-certificate.json'
import bankAccountOpening from './bank-account-opening.json'
import ayushmanCard from './ayushman-card.json'
import incomeCertificate from './income-certificate.json'
import casteCertificate from './caste-certificate.json'
import lpgSubsidy from './lpg-subsidy.json'
import rtiApplication from './rti-application.json'

export const FORMS = [
  nspScholarship,
  pan93,
  rationCard,
  pensionLifeCertificate,
  bankAccountOpening,
  ayushmanCard,
  incomeCertificate,
  casteCertificate,
  lpgSubsidy,
  rtiApplication,
]

export function getForm(id) {
  return FORMS.find((form) => form.id === id) ?? null
}

/** Fields we can fill from a DigiLocker profile without asking anything. */
export function prefillableFields(form) {
  return form.fields.filter((f) => f.source === 'digilocker')
}

/** Fields the voice flow must actually ask about. */
export function askableFields(form, profile) {
  return form.fields.filter(
    (f) => f.source !== 'digilocker' || !profile?.[f.profileKey],
  )
}

/**
 * Identify which template a scanned form is, from OCR text.
 *
 * Deliberately dumb: count how many of each template's keywords appear in the
 * OCR output, weighting longer phrases higher because "ration card" appearing
 * is far more telling than "card". No model involved, so the result is
 * reproducible and debuggable — if it misidentifies a form you can read the
 * keyword list and see exactly why.
 *
 * Returns matches sorted best-first, each with a 0..1 confidence.
 */
export function identifyForm(ocrText) {
  const haystack = ocrText.toLowerCase().replace(/\s+/g, ' ')

  const scored = FORMS.map((form) => {
    let score = 0
    const hits = []
    for (const keyword of form.ocrKeywords) {
      if (haystack.includes(keyword.toLowerCase())) {
        // A three-word phrase is worth more than a bare word.
        score += keyword.split(' ').length
        hits.push(keyword)
      }
    }
    const maxPossible = form.ocrKeywords.reduce(
      (sum, k) => sum + k.split(' ').length,
      0,
    )
    return {
      form,
      hits,
      score,
      confidence: maxPossible ? score / maxPossible : 0,
    }
  })

  return scored.filter((m) => m.score > 0).sort((a, b) => b.score - a.score)
}
